"""matplotlib.image — image handling stubs."""

import sys as _sys
import numpy as _np


_image_warned = set()

def _image_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _image_warned:
        _image_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] image.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class AxesImage:
    """Stub AxesImage."""
    __getattr__ = _image_getattr_fallback

    def __init__(self, ax=None, **kwargs):
        self.axes = ax
        self._data = None
        self._cmap = kwargs.get('cmap', 'viridis')
        self._norm = kwargs.get('norm', None)
        self._extent = kwargs.get('extent', None)
        self._origin = kwargs.get('origin', None)
        self._interpolation = kwargs.get('interpolation', None)
        self._filterrad = kwargs.get('filterrad', 4.0)
        self._filternorm = kwargs.get('filternorm', True)
        self._resample = kwargs.get('resample', None)
        self._alpha = kwargs.get('alpha', None)
        self._visible = True
        self._zorder = kwargs.get('zorder', 0)
        self._label = kwargs.get('label', '')
        self._clim = (None, None)

    # Data
    def set_data(self, A):     self._data = A
    def get_array(self):       return self._data
    def set_array(self, A):    self._data = A
    # Colormap / normalization
    def set_clim(self, vmin=None, vmax=None):
        if vmax is None and hasattr(vmin, '__len__'):
            vmin, vmax = vmin[0], vmin[1]
        self._clim = (vmin, vmax)
    def get_clim(self):        return self._clim
    def set_cmap(self, cmap):  self._cmap = cmap
    def get_cmap(self):        return self._cmap
    def set_norm(self, n):     self._norm = n
    def get_norm(self):        return self._norm
    def autoscale(self):       pass
    def autoscale_None(self):  pass
    # Spatial
    def set_extent(self, extent): self._extent = extent
    def get_extent(self):      return self._extent
    def set_origin(self, o):   self._origin = o
    def get_origin(self):      return self._origin
    # Sampling
    def set_interpolation(self, i): self._interpolation = i
    def get_interpolation(self): return self._interpolation
    def set_filterrad(self, f): self._filterrad = float(f)
    def get_filterrad(self):   return self._filterrad
    def set_filternorm(self, b): self._filternorm = bool(b)
    def get_filternorm(self):  return self._filternorm
    def set_resample(self, r): self._resample = r
    def get_resample(self):    return self._resample
    # State
    def set_alpha(self, a):    self._alpha = a
    def get_alpha(self):       return self._alpha
    def set_visible(self, v):  self._visible = bool(v)
    def get_visible(self):     return self._visible
    def set_zorder(self, z):   self._zorder = z
    def get_zorder(self):      return self._zorder
    def set_label(self, l):    self._label = l
    def get_label(self):       return self._label
    # Lifecycle
    def remove(self):          pass
    def draw(self, renderer):  pass
    def contains(self, ev):    return False, {}
    def get_window_extent(self, renderer=None): return None
    def get_size(self):
        if self._data is None: return (0, 0)
        try:    return self._data.shape[:2]
        except Exception: return (0, 0)
    def update_from(self, other):
        for attr in ('cmap', 'norm', 'extent', 'alpha', 'visible'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass
    def update(self, props):
        for k, v in (props or {}).items():
            setter = getattr(self, f'set_{k}', None)
            if setter is not None:
                try: setter(v)
                except Exception: pass
    def to_rgba(self, x, alpha=None, bytes=False, norm=True):
        """Run scalar data through (norm → cmap) to get an RGBA array."""
        arr = _np.asarray(x)
        # If it's already RGB/RGBA we just pass it through.
        if arr.ndim == 3 and arr.shape[-1] in (3, 4):
            if arr.shape[-1] == 3:
                # Add alpha channel.
                a = _np.ones(arr.shape[:-1] + (1,),
                              dtype=arr.dtype if arr.dtype != _np.uint8 else float)
                if arr.dtype == _np.uint8: a = a * 255
                arr = _np.concatenate([arr, a], axis=-1)
            return arr.astype(_np.uint8) if bytes else arr
        # Scalar data — apply norm + cmap.
        if norm and self._norm is not None:
            arr = self._norm(arr)
        elif norm:
            from matplotlib.colors import Normalize
            vmin, vmax = self._clim
            if vmin is None: vmin = float(_np.nanmin(arr))
            if vmax is None: vmax = float(_np.nanmax(arr))
            n = Normalize(vmin=vmin, vmax=vmax)
            arr = n(arr)
        cmap = self._cmap
        if isinstance(cmap, str):
            try:
                from matplotlib.cm import get_cmap
                cmap = get_cmap(cmap)
            except Exception:
                cmap = None
        if cmap is not None:
            try:
                rgba = cmap(arr, alpha=alpha, bytes=bytes)
                return rgba
            except Exception:
                pass
        # Fallback: monochrome ramp.
        rgba = _np.stack([arr, arr, arr, _np.ones_like(arr)], axis=-1)
        return (_np.clip(rgba, 0, 1) * 255).astype(_np.uint8) if bytes else rgba

    def get_cursor_data(self, event):
        """Return the data value at the cursor's location, or None
        if outside the image. Mirrors upstream's cursor inspection."""
        if self._data is None:
            return None
        try:
            xdata, ydata = event.xdata, event.ydata
        except AttributeError:
            return None
        if xdata is None or ydata is None:
            return None
        arr = self._data
        H, W = arr.shape[:2]
        ext = self._extent or (-0.5, W - 0.5, -0.5, H - 0.5)
        x0, x1, y0, y1 = ext
        # Map data coords to array indices.
        if x1 == x0 or y1 == y0:
            return None
        col = int((xdata - x0) / (x1 - x0) * W)
        row = int((ydata - y0) / (y1 - y0) * H)
        if self._origin == 'upper' or self._origin is None:
            row = H - 1 - row
        if 0 <= row < H and 0 <= col < W:
            return arr[row, col]
        return None

    def get_window_extent(self, renderer=None):
        """Bbox in display coords — for the shim we return the data extent
        as a Bbox since the renderer is plotly, not a pixel canvas."""
        from matplotlib.transforms import Bbox
        if self._extent is not None:
            x0, x1, y0, y1 = self._extent
            return Bbox.from_extents(x0, y0, x1, y1)
        if self._data is not None:
            H, W = self._data.shape[:2]
            return Bbox.from_extents(-0.5, -0.5, W - 0.5, H - 0.5)
        return Bbox.from_extents(0, 0, 1, 1)

    def make_image(self, renderer=None, magnification=1.0, unsampled=False):
        """Produce the RGBA pixel buffer that would be drawn. For the
        plotly-backed shim we just convert the scalar/RGB data into
        RGBA and return it alongside the lower-left offset."""
        if self._data is None:
            return _np.zeros((1, 1, 4), dtype=_np.uint8), 0, 0, None
        rgba = self.to_rgba(self._data, alpha=self._alpha, bytes=True)
        return rgba, 0, 0, None

    def write_png(self, fname):
        try:
            imsave(fname, self._data)
        except Exception: pass


def imread(fname, format=None):
    """Read an image file into a numpy array. Uses PIL when available
    so callers actually get the image data, not a zero array."""
    try:
        from PIL import Image as _PILImage
        im = _PILImage.open(fname)
        if im.mode not in ('RGB', 'RGBA', 'L'):
            im = im.convert('RGBA')
        arr = _np.asarray(im)
        # Normalize to float in [0,1] like upstream does for non-PNG inputs.
        if arr.dtype == _np.uint8:
            return arr.astype(float) / 255.0
        return arr
    except Exception:
        # Last-ditch: a single 1×1 transparent pixel rather than 100×100
        # of opaque black (which silently produces garbage downstream).
        return _np.zeros((1, 1, 4), dtype=float)


def imsave(fname, arr, *, vmin=None, vmax=None, cmap=None, format=None,
            origin=None, dpi=100, metadata=None, pil_kwargs=None):
    """Save an array as an image file via PIL. Honours vmin/vmax/cmap
    for scalar inputs, mirroring upstream's API."""
    arr = _np.asarray(arr)
    try:
        from PIL import Image as _PILImage
    except Exception:
        return  # No PIL available — silently skip rather than crash.

    # Scalar data → apply colormap.
    if arr.ndim == 2:
        from matplotlib.colors import Normalize
        if vmin is None: vmin = float(_np.nanmin(arr))
        if vmax is None: vmax = float(_np.nanmax(arr))
        norm = Normalize(vmin=vmin, vmax=vmax)
        normalized = norm(arr)
        if cmap is not None:
            if isinstance(cmap, str):
                from matplotlib.cm import get_cmap
                cmap = get_cmap(cmap)
            rgba = cmap(normalized, bytes=True)
        else:
            g = (_np.clip(normalized, 0, 1) * 255).astype(_np.uint8)
            rgba = _np.stack([g, g, g, _np.full_like(g, 255)], axis=-1)
    elif arr.ndim == 3:
        if arr.dtype != _np.uint8:
            rgba = (_np.clip(arr, 0, 1) * 255).astype(_np.uint8)
        else:
            rgba = arr
        if rgba.shape[-1] == 3:
            alpha = _np.full(rgba.shape[:-1] + (1,), 255, dtype=_np.uint8)
            rgba = _np.concatenate([rgba, alpha], axis=-1)
    else:
        return

    if origin == 'lower':
        rgba = rgba[::-1]

    im = _PILImage.fromarray(rgba, mode='RGBA')
    im.save(fname, format=format, dpi=(dpi, dpi), **(pil_kwargs or {}))


# ─── Added: missing public Image classes from upstream image.py ───
#
# These mirror :class:`AxesImage` for variants tied to a bounding box,
# the figure (rather than an axes), an non-uniform grid, or a pcolor-
# style image. Same set/get accessors so client code that polls them
# still works.


class _BaseImage(AxesImage):
    """Shared accessors used by all the image variants below."""

    def __init__(self, **kwargs):
        super().__init__(ax=None, **kwargs)
        self._origin = kwargs.get('origin', 'upper')
        self._interpolation = kwargs.get('interpolation', 'nearest')

    def get_origin(self):                 return self._origin
    def set_interpolation(self, value):   self._interpolation = value
    def get_interpolation(self):          return self._interpolation


class BboxImage(_BaseImage):
    """Image rendered inside an arbitrary bounding box rather than tied
    to data coordinates. ``bbox`` is queried by the renderer at draw
    time for the target rectangle."""

    def __init__(self, bbox, *, cmap=None, norm=None, interpolation=None,
                 origin=None, **kwargs):
        super().__init__(cmap=cmap, norm=norm, interpolation=interpolation,
                         origin=origin, **kwargs)
        self.bbox = bbox

    def get_window_extent(self, renderer=None):
        return self.bbox


class FigureImage(_BaseImage):
    """Image positioned in figure coordinates (not data coordinates) —
    used for figure-level backgrounds, watermarks, etc."""

    def __init__(self, fig, *, cmap=None, norm=None, offsetx=0, offsety=0,
                 origin=None, **kwargs):
        super().__init__(cmap=cmap, norm=norm, origin=origin, **kwargs)
        self.figure = fig
        self.ox = offsetx
        self.oy = offsety


class NonUniformImage(_BaseImage):
    """Image whose pixels are placed at arbitrary (non-uniformly spaced)
    x/y coordinates. Use :meth:`set_data` with ``(x, y, A)`` to attach
    the coordinate vectors alongside the pixel values."""

    def __init__(self, ax, *, interpolation='nearest', **kwargs):
        super().__init__(interpolation=interpolation, **kwargs)
        self.axes = ax
        self._x = None
        self._y = None

    def set_data(self, x, y, A):
        self._x = _np.asarray(x)
        self._y = _np.asarray(y)
        self._data = _np.asarray(A)


class PcolorImage(_BaseImage):
    """Image variant produced by :func:`pcolorfast`. Like
    :class:`NonUniformImage` but the edges, not centres, of each cell
    are specified."""

    def __init__(self, ax, x=None, y=None, A=None, *, cmap=None, norm=None,
                 **kwargs):
        super().__init__(cmap=cmap, norm=norm, **kwargs)
        self.axes = ax
        self._x = _np.asarray(x) if x is not None else None
        self._y = _np.asarray(y) if y is not None else None
        if A is not None:
            self._data = _np.asarray(A)


def composite_images(images, renderer=None, magnification=1.0):
    """Composite a list of image artists into a single RGBA array. The
    shim assumes solid stacking in order — later images overlay earlier
    ones where their alpha channel is non-zero. Returns ``(rgba, x, y)``
    where ``(x, y)`` is the lower-left corner of the composite (always
    ``(0, 0)`` for the shim's coordinate-free version).
    """
    if not images:
        return _np.zeros((1, 1, 4), dtype=_np.uint8), 0, 0
    # Pick the max shape across all images for the canvas.
    arrays = [getattr(im, '_data', None) for im in images]
    arrays = [a for a in arrays if a is not None]
    if not arrays:
        return _np.zeros((1, 1, 4), dtype=_np.uint8), 0, 0
    H = max(a.shape[0] for a in arrays)
    W = max(a.shape[1] for a in arrays)
    out = _np.zeros((H, W, 4), dtype=float)
    for a in arrays:
        h, w = a.shape[:2]
        rgba = a if a.ndim == 3 and a.shape[2] == 4 else _np.dstack(
            [a, a, a, _np.ones_like(a)] if a.ndim == 2 else
            [*[a[..., i] for i in range(a.shape[2])], _np.ones(a.shape[:2])])
        # alpha-composite over.
        alpha = rgba[..., 3:4]
        out[:h, :w] = rgba * alpha + out[:h, :w] * (1 - alpha)
    return _np.clip(out, 0, 1), 0, 0


def pil_to_array(pilImage):
    """Convert a PIL image to a numpy array. Handles RGBA, RGB, L, and
    P modes; otherwise falls through to a generic conversion."""
    if pilImage is None:
        return _np.zeros((1, 1, 4), dtype=_np.uint8)
    try:
        mode = getattr(pilImage, 'mode', 'RGBA')
        if mode == 'P':
            pilImage = pilImage.convert('RGBA')
        elif mode == 'L':
            return _np.array(pilImage, dtype=_np.uint8)
        elif mode not in ('RGB', 'RGBA'):
            pilImage = pilImage.convert('RGBA')
        return _np.asarray(pilImage)
    except Exception:
        return _np.zeros((1, 1, 4), dtype=_np.uint8)


def thumbnail(infile, thumbfile, scale=0.1, interpolation='bilinear',
              preview=False):
    """Make a thumbnail of an image at ``infile`` and save it to
    ``thumbfile`` scaled by ``scale``. Returns the figure used to draw
    it — None when the shim has no PIL available."""
    try:
        from PIL import Image as _PILImage
        im = _PILImage.open(infile)
        w, h = im.size
        im = im.resize((max(1, int(w * scale)), max(1, int(h * scale))))
        im.save(thumbfile)
        return None
    except Exception:
        return None


