# ─── Added: NonUniformImage methods ─────────────────────────────────


def _nui_make_image(self, renderer=None, magnification=1.0, unsampled=False):
    return self._data, 0, 0, None
def _nui_get_cursor_data(self, event): return None
def _nui_set_array(self, A):
    if hasattr(self, '_data') and self._data is not None and self._x is not None:
        self._data = A
def _nui_set_filternorm(self, b):  self._filternorm = bool(b)
def _nui_set_filterrad(self, r):   self._filterrad = float(r)
def _nui_set_norm(self, n):        self._norm = n

NonUniformImage.make_image      = _nui_make_image
NonUniformImage.get_cursor_data = _nui_get_cursor_data
NonUniformImage.set_array       = _nui_set_array
NonUniformImage.set_filternorm  = _nui_set_filternorm
NonUniformImage.set_filterrad   = _nui_set_filterrad
NonUniformImage.set_norm        = _nui_set_norm


# ─── Real implementations for image subclasses ─────────────────────


def _bbox_image_contains(self, mouseevent):
    """Hit-test against the bounding box."""
    if self.bbox is None:
        return False, {}
    try:
        x0, y0, x1, y1 = self.bbox.x0, self.bbox.y0, self.bbox.x1, self.bbox.y1
        if x0 <= mouseevent.x <= x1 and y0 <= mouseevent.y <= y1:
            return True, {}
    except Exception:
        pass
    return False, {}


BboxImage.contains = _bbox_image_contains
# make_image / get_cursor_data inherited from AxesImage (real impls).
